const parts = msg.topic.split("/");
if (parts.length !== 4 || typeof msg.payload.value !== "number") {
    return null;
}
msg.payload = [{
    measurement: "telemetry",
    tags:   { hive_id: parts[1], sensor: parts[3] },
    fields: { value: msg.payload.value },
    timestamp: new Date(msg.payload.ts)
}];
return msg;

// apiary/{hive_id}/status
const parts = msg.topic.split("/");
if (parts.length !== 3 || msg.payload !== "online") {
    return null;
}
msg.hive_id = parts[1];
return msg;

const SECTIONS = ["heater", "fan_temp", "fan_humidity"];
const file = msg.payload || {};
const defaults = file.defaults || {};
const override = (file.hives || {})[msg.hive_id] || {};

// Merge per section, field by field: an override may redefine a single threshold
const cfg = {};
for (const s of SECTIONS) {
    cfg[s] = Object.assign({}, defaults[s], override[s]);
}

const num = (v) => typeof v === "number" && isFinite(v);
const valid =
    num(cfg.heater.on_below) && num(cfg.heater.off_above) &&
    cfg.heater.on_below < cfg.heater.off_above &&
    ["fan_temp", "fan_humidity"].every((s) =>
        num(cfg[s].on_above) && num(cfg[s].off_below) && cfg[s].off_below < cfg[s].on_above);

if (!valid) {
    node.warn(`invalid thresholds for ${msg.hive_id}, config not published: ${JSON.stringify(cfg)}`);
    return null;
}
return { topic: `apiary/${msg.hive_id}/config`, payload: cfg };

// apiary/{hive_id}/config
const parts = msg.topic.split("/");
const c = msg.payload;
if (parts.length !== 3 || !c || !c.heater || !c.fan_temp || !c.fan_humidity) {
    return null;
}
const config = flow.get("config") || {};
config[parts[1]] = c;
flow.set("config", config);
node.status({ text: `${parts[1]} heater ${c.heater.on_below}/${c.heater.off_above}` });
return null;

// apiary/{hive_id}/actuators/{heater|fan}/state: what the hive CONFIRMED, not what we asked for
const parts = msg.topic.split("/");
if (parts.length !== 5 || (msg.payload !== "ON" && msg.payload !== "OFF")) {
    return null;
}
const states = flow.get("states") || {};
states[parts[1]] = states[parts[1]] || {};
states[parts[1]][parts[3]] = msg.payload;
flow.set("states", states);
return null;

// apiary/{hive_id}/sensors/{sensor}
const parts = msg.topic.split("/");
if (parts.length !== 4 || !msg.payload || typeof msg.payload.value !== "number") {
    return null;
}
const hive = parts[1];
const sensor = parts[3];
if (sensor !== "brood_temp" && sensor !== "humidity") {
    return null;
}

const values = flow.get("values") || {};
const v = values[hive] = values[hive] || {};
v[sensor] = msg.payload.value;
flow.set("values", values);

const cfg = (flow.get("config") || {})[hive];
if (!cfg) {
    const warned = context.get("warned") || {};
    if (!warned[hive]) {
        warned[hive] = true;
        context.set("warned", warned);
        node.warn(`no config for ${hive} yet: control loop idle`);
    }
    return null;
}

const confirmed = (flow.get("states") || {})[hive] || {};
const allNeeds = flow.get("needs") || {};
const needs = allNeeds[hive] = allNeeds[hive] || {};

// Hysteresis with memory: a need changes only when the value leaves the band.
// After a Node-RED restart the memory is rebuilt from the confirmed actuator state;
// if that is unknown too, the need stays undefined until the value leaves the band.
function update(name, actuator, value, turnsOn, turnsOff) {
    if (needs[name] === undefined && confirmed[actuator] !== undefined) {
        needs[name] = confirmed[actuator] === "ON";
    }
    if (value === undefined) {
        return;
    }
    if (needs[name] !== true && turnsOn(value)) {
        needs[name] = true;
    } else if (needs[name] !== false && turnsOff(value)) {
        needs[name] = false;
    }
}
update("heaterNeed", "heater", v.brood_temp,
    (t) => t < cfg.heater.on_below, (t) => t > cfg.heater.off_above);
update("fanTempNeed", "fan", v.brood_temp,
    (t) => t > cfg.fan_temp.on_above, (t) => t < cfg.fan_temp.off_below);
update("fanHumNeed", "fan", v.humidity,
    (h) => h > cfg.fan_humidity.on_above, (h) => h < cfg.fan_humidity.off_below);
flow.set("needs", allNeeds);

// Desired state. Heating wins over ventilation: a running fan would waste the heat.
const heater = needs.heaterNeed;
let fan;
if (heater === true) {
    fan = false;
} else if (heater === false) {
    if (needs.fanTempNeed === true || needs.fanHumNeed === true) {
        fan = true;
    } else if (needs.fanTempNeed === false && needs.fanHumNeed === false) {
        fan = false;
    }
}

// Command only what differs from the confirmed state. Nothing is retried on a timer:
// while the hive has not confirmed, the next reading emits the command again.
const sent = context.get("sent") || {};
const out = [];
for (const [actuator, want] of [["heater", heater], ["fan", fan]]) {
    if (want === undefined) {
        continue;
    }
    const cmd = want ? "ON" : "OFF";
    const key = `${hive}/${actuator}`;
    if (confirmed[actuator] === cmd) {
        delete sent[key];
        continue;
    }
    // brood_temp and humidity of the same tick share "ts": one command per tick is enough
    if (sent[key] && sent[key].cmd === cmd && sent[key].ts === msg.payload.ts) {
        continue;
    }
    sent[key] = { cmd: cmd, ts: msg.payload.ts };
    out.push({ topic: `apiary/${hive}/actuators/${actuator}/cmd`, payload: cmd });
}
context.set("sent", sent);

const onOff = (b) => (b === undefined ? "?" : b ? "ON" : "OFF");
const t = v.brood_temp === undefined ? "?" : v.brood_temp.toFixed(1);
const h = v.humidity === undefined ? "?" : v.humidity.toFixed(0);
node.status({
    fill: heater ? "red" : fan ? "blue" : "grey",
    shape: "dot",
    text: `${hive} ${t}°C ${h}% heater ${onOff(heater)} fan ${onOff(fan)}`
});
return [out];

// apiary/{hive_id}/actuators/{heater|fan}/state
const parts = msg.topic.split("/");
if (parts.length !== 5 || (msg.payload !== "ON" && msg.payload !== "OFF")) {
    return null;
}
// The state payload carries no "ts": the write time is the best timestamp available
msg.payload = [{
    measurement: "actuator",
    tags:   { hive_id: parts[1], actuator: parts[3] },
    fields: { state: msg.payload === "ON" ? 1.0 : 0.0 },
    timestamp: new Date()
}];
return msg;
